import React, { useRef, useState } from 'react';
import { PageContainer } from '@ant-design/pro-layout';
import type { ProColumns, ActionType } from '@ant-design/pro-table';
import ProTable from '@ant-design/pro-table';
import { alarmAudits } from '@/services/api';
import type { API } from '@/services/typings';
import { SaveCsv, csvFormat, getTablePaginationConfig, t } from '../../../global';
import { useIntl } from '@umijs/max';
import { Breadcrumb, Button, Space, Tooltip, Typography } from 'antd';

const AuditList: React.FC = () => {
  const actionRef = useRef<ActionType>();
  const [pageParams, setPageParams] = useState<Partial<API.PageParams>>();
  const intl = useIntl();

  const plain = (text: string, defaultMessage = '') => t(`pages.AuditList.AlarmAuditList.${text}`, true, defaultMessage || text, intl) as string;
  const fromTitle = () => plain('Login Device / Controlling Side', 'From');
  const targetTitle = () => plain('Login Account / Controlled Device', 'Target');
  const fromTip = () => plain('From Tip', 'Account / Login Device / Controlling Side');
  const targetTip = () => plain('Target Tip', 'Login Account / Controlled Device');
  const loginAccountSearchTip = () => plain(
    'Login Account Search Tip',
    'Login-account alarm logs always support Login Account search. Connection-type alarm logs require controlled client version >= 1.4.9 for controlling Login Account search.',
  );

  const typeEnumMap = (i: number) => {
    switch (i) {
      case 0:
        return plain(
          'IP whiltelist',
          'Access attempt outside the IP whiltelist',
        );
      case 1:
        return plain('ExceedThirtyAccessAttempts',
          'Over 30 consecutive access attempts');
      case 2:
        return plain(
          'MultipleAccessAttemptsWithinOneMinute',
          'Multiple access attempts within one minute',
        );
      case 3:
        return plain(
          'ExceedThirtyLoginAttempts',
          'Over 30 consecutive login attempts',
        );
      case 4:
        return plain(
          'MultipleLoginsAttemptsWithinOneMinute',
          'Multiple login attempts within one minute',
        );
      case 5:
        return plain(
          'MultipleLoginsAttemptsWithinOneHour',
          'Multiple login attempts within one hour',
        );
      case 6:
        return plain(
          'ExceedIPv6PrefixAttempts',
          'Too many consecutive access attempts from a single IPv6 prefix',
        );
      case 7:
        return plain(
          'TerminalOsLoginBackoff',
          'Multiple failed Terminal (Run as administrator) login attempts (wrong username/password)',
        );
      case 8:
        return plain(
          'TerminalOsLoginConcurrency',
          'Multiple simultaneous Terminal (Run as administrator) login attempts',
        );
      case 9:
        return plain(
          'SessionScopeViolation',
          'Session scope violation',
        );
      default:
        return i.toString();
    }
  };

  const renderTarget = (record: API.AlarmAuditListItem) => {
    const type = record.typ ?? 0;
    if ([0, 1, 2, 6, 7, 8, 9].includes(type)) {
      return record.device ?? '-';
    } else if ([3, 4, 5].includes(type)) {
      if (!record.account_email) return record.account ?? '-';
      return record.account ? `${record.account}\n${record.account_email}` : record.account_email;
    }
    return '-';
  };

  const renderMultiline = (text: string) => {
    const lines = text.split('\n');
    if (lines.length == 1) {
      return lines[0];
    }
    return (
      <Space direction="vertical" size={0}>
        <Typography.Text>{lines[0]}</Typography.Text>
        <Typography.Text type="secondary" style={{ whiteSpace: 'pre-line' }}>
          {lines.slice(1).join('\n')}
        </Typography.Text>
      </Space>
    );
  };

  const renderFromText = (record: API.AlarmAuditListItem) => {
    const type = record.typ ?? 0;
    if ([0, 1, 2, 6, 7, 8].includes(type)) {
      let txt = '';
      let local_info = {} as any;
      try {
        local_info = JSON.parse(record.info || '{}');
        if (local_info['id']) txt += local_info['id'];
        if (local_info['name']) {
          if (txt) txt += '-';
          txt += local_info['name'];
        }
        if (local_info['ip']) {
          txt += '@' + local_info['ip'];
        }
      } catch (e) { }
      if (record.account || record.account_email) {
        let account = record.account || '';
        if (record.account_email) {
          account = account ? `${account}\n${record.account_email}` : record.account_email;
        }
        return txt ? `${account}\n${txt}` : account;
      }
      return txt;
    } else if (type === 9) {
      let txt = '';
      let local_info = {} as any;
      try {
        local_info = JSON.parse(record.info || '{}');
        if (local_info.peer_id) txt += local_info.peer_id;
        if (local_info.ip) {
          txt = txt ? `${txt}@${local_info.ip}` : local_info.ip;
        }
        let detail = '';
        if (local_info.conn_type) detail += local_info.conn_type;
        if (local_info.message) {
          if (detail) detail += ' ';
          detail += local_info.message;
        }
        if (detail) {
          txt = txt ? `${txt}\n${detail}` : detail;
        }
      } catch (e) { }
      if (record.account || record.account_email) {
        let account = record.account || '';
        if (record.account_email) {
          account = account ? `${account}\n${record.account_email}` : record.account_email;
        }
        return txt ? `${account}\n${txt}` : account;
      }
      return txt || '-';
    } else if ([3, 4, 5].includes(type)) {
      let txt = '';
      let local_info = {} as any;
      try {
        local_info = JSON.parse(record.info || '{}');
        const device_info = local_info['device_info'] as any;
        if (device_info['os']) txt += device_info['os'];
        if (device_info['type']) {
          if (txt) txt += ' ';
          txt += device_info['type'];
        }
        if (device_info['name']) {
          if (txt) txt += '-';
          txt += device_info['name'];
        }
        if (local_info['ip']) {
          txt += '@' + local_info['ip'];
        }
      } catch (e) { }
      return txt;
    } else {
      return '-';
    }
  };

  const renderFrom = (record: API.AlarmAuditListItem) => {
    return renderMultiline(renderFromText(record));
  };

  const exportCsv = async () => {
    let allItems: API.AlarmAuditListItem[] = [];
    let total = 0;
    const pageSize = 100;
    let current = 0;
    do {
      current++;
      const items = await alarmAudits({ ...pageParams, current: current, pageSize: pageSize });
      if (total == 0 && items.total != null) {
        total = items.total;
      }
      if (items.data != null) {
        allItems = allItems.concat(items.data);
      }
    } while (current < 10 && pageSize * current < total);

    const titles = [
      plain('Type'),
      fromTitle(),
      targetTitle(),
      plain('Event Time'),
    ];
    const rows: string[][] = [];
    allItems.forEach((record) => {
      const row: string[] = [];
      row.push(typeEnumMap(record.typ || 0));
      row.push(csvFormat(renderFromText(record) || '-'));
      row.push(csvFormat(renderTarget(record) || '-'));
      row.push(csvFormat(new Date((record.created_at || 0) * 1000).toLocaleString()));
      rows.push(row);
    });
    SaveCsv(titles, rows, plain('exportFilename', 'AlarmAudit'));
  };

  const columns: ProColumns<API.AlarmAuditListItem>[] = [
    {
      title: t('Type'),
      dataIndex: 'typ',
      valueType: 'select',
      valueEnum: {
        0: {
          text: typeEnumMap(0),
        },
        1: {
          text: typeEnumMap(1),
        },
        2: {
          text: typeEnumMap(2),
        },
        3: {
          text: typeEnumMap(3),
        },
        4: {
          text: typeEnumMap(4),
        },
        5: {
          text: typeEnumMap(5),
        },
        6: {
          text: typeEnumMap(6),
        },
        7: {
          text: typeEnumMap(7),
        },
        8: {
          text: typeEnumMap(8),
        },
        9: {
          text: typeEnumMap(9),
        },
      },
      render: (_, record) => typeEnumMap(record.typ || 0),
    },
    {
      title: fromTitle(),
      tip: fromTip(),
      search: false,
      hideInSearch: true,
      render: (_, record) => {
        return renderFrom(record);
      },
    },
    {
      title: targetTitle(),
      tip: targetTip(),
      hideInSearch: true,
      render: (_, record) => {
        return renderMultiline(renderTarget(record));
      },
    },
    {
      title: plain('Login Account'),
      dataIndex: 'account',
      hideInTable: true,
      tip: loginAccountSearchTip(),
    },
    {
      title: plain('Device ID'),
      dataIndex: 'device',
      hideInDescriptions: true,
      hideInTable: true,
      tip: plain('Controlled Device'),
    },
    {
      title: plain('Device Name'),
      dataIndex: 'report_device_name',
      hideInDescriptions: true,
      hideInTable: true,
      tip: plain('Controlled Device'),
    },
    {
      title: plain('Event Time'),
      dataIndex: 'created_at',
      valueType: 'dateTime',
      render: (_, record) => new Date((record.created_at || 0) * 1000).toLocaleString(),
    },
  ];

  return (
    <PageContainer
      breadcrumbRender={() => (
        <Breadcrumb items={[
          { title: t('menu.list.audit-list', true) },
          { title: t('menu.list.audit-list.Alarm', true) },
        ]} />
      )}
    >
      <ProTable<API.AlarmAuditListItem, API.PageParams>
        headerTitle={t('Log List')}
        columnsState={{ persistenceType: 'localStorage', persistenceKey: 'alarmlist_columns_state' }}
        actionRef={actionRef}
        rowKey="guid"
        search={{
          labelWidth: 140,
        }}
        request={alarmAudits}
        columns={columns}
        beforeSearchSubmit={(params) => {
          setPageParams(params);
          return params;
        }}
        toolBarRender={() => [
          <Tooltip title={t('exportCsvTip', true, 'Export up to 1000 records at a time')}>
            <Button type="default" onClick={exportCsv}>
              {t('Export as csv')}
            </Button>
          </Tooltip>,
        ]}
        pagination={getTablePaginationConfig("alarm_audit_list")}
      />
    </PageContainer>
  );
};

export default AuditList;
